func (o *Node) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "GameServers":
		rels, ok := retrieved.(GameServerSlice)
		if !ok {
			return fmt.Errorf("node cannot load %T as %q", retrieved, name)
		}

		o.R.GameServers = rels

		for _, rel := range rels {
			if rel != nil {
				rel.R.Node = o
			}
		}
		return nil
	case "NodeSyncQueues":
		rels, ok := retrieved.(NodeSyncQueueSlice)
		if !ok {
			return fmt.Errorf("node cannot load %T as %q", retrieved, name)
		}

		o.R.NodeSyncQueues = rels

		for _, rel := range rels {
			if rel != nil {
				rel.R.Node = o
			}
		}
		return nil
	case "PeerSyncState":
		rel, ok := retrieved.(*PeerSyncState)
		if !ok {
			return fmt.Errorf("node cannot load %T as %q", retrieved, name)
		}

		o.R.PeerSyncState = rel

		if rel != nil {
			rel.R.Node = o
		}
		return nil
	case "RemoteServerCaches":
		rels, ok := retrieved.(RemoteServerCacheSlice)
		if !ok {
			return fmt.Errorf("node cannot load %T as %q", retrieved, name)
		}

		o.R.RemoteServerCaches = rels

		for _, rel := range rels {
			if rel != nil {
				rel.R.Node = o
			}
		}
		return nil
	default:
		return fmt.Errorf("node has no relationship %q", name)
	}
}

